def transform(name,text):
 text=previous_transform(name,text).replace('native_onpolicy_arm_collection_v55','native_onpolicy_arm_collection_v56').replace('native_onpolicy_calibration_data_v38','native_onpolicy_calibration_data_v39').replace('native_prepared_FIT_collection_v10','native_prepared_FIT_collection_v11').replace('native_render_overlap_v2','native_render_overlap_v3')
 text=text.replace('outputs/native_onpolicy_arm_collection_v56/CPU_contract_checks_v3.json','outputs/native_onpolicy_arm_collection_v56/CPU_contract_checks_v1.json').replace('outputs/native_onpolicy_arm_collection_v56/CPU_actual_host_exit_v3.json','outputs/native_onpolicy_arm_collection_v56/CPU_actual_host_exit_v1.json').replace('outputs/native_render_overlap_v3/CPU_contract_checks_v2.json','outputs/native_render_overlap_v3/CPU_contract_checks_v1.json').replace('outputs/native_render_overlap_v3/CPU_checks_actual_host_exit_v4.json','outputs/native_render_overlap_v3/CPU_actual_host_exit_v1.json')
 if name=='collection_plan.py':
  anchor='  from native_unread_capture_full_v1.budget import require_planned_full_batch\n';assert text.count(anchor)==1;text=text.replace(anchor,PLAN+anchor)
 if name=='runtime.py':
  anchor='  render_overlap.close()\n';assert text.count(anchor)==1;text=text.replace(anchor,anchor+CLEANUP)
 return text.replace('outputs/native_render_overlap_v3/CPU_contract_checks_v1.json','outputs/native_render_overlap_v3/CPU_contract_checks_v2.json').replace('outputs/native_render_overlap_v3/CPU_actual_host_exit_v1.json','outputs/native_render_overlap_v3/CPU_actual_host_exit_v2.json')
